with a as(select * from public.authors where open_library_id=any(array['OL236174A','OL1213378A','OL74490A','OL800926A','OL2623989A','OL135196A','OL22973A','OL24809A','OL492907A','OL561656A']::text[])),w as(select * from public.works where open_library_id=any(array['OL2096536W','OL1966487W','OL14867077W','OL1326316W','OL14871157W','OL20659782W','OL857555W','OL15253352W','OL3123542W','OL14933747W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789027408112','9781568492506','9789046806517','9781416594789','9789029530149','9789021494029','9789041403704','9789044839142','9789029039116','9789074336024','9789029525466','9789055796847']::text[]) or open_library_edition_id=any(array['OL24678434M','OL12189606M','OL24328108M','OL24391629M','OL24947100M','OL25098874M','OL9099498M','OL41916184M','OL36662942M','OL24328241M','OL46540080M','OL24228364M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987109001 and 987109999),'editions',(select count(*) from public.editions where id between 987209001 and 987209999),'authors',(select count(*) from public.authors where id between 987309001 and 987309999))) as preflight;
